//! Task 8.6: squint's conformance fixtures from a running server (table-manners 4.3–4.6): a
//! served run with its session and correlation ids, the runs page, the session after a check, and
//! both refusals. An estimate is never a run (task 9.4), so none of these is one. Generated by driving `squint serve`, the machine values fixed, and held like the
//! other fixtures: the committed copy under `fixtures/contract/squint/` must equal what squint
//! produces now; `UPDATE_CONTRACT_FIXTURES=1` rewrites it after a deliberate change.
#![cfg(feature = "testkit")]
#![allow(clippy::unwrap_used)]

use std::path::{Path, PathBuf};
use std::process::Command;

use serde_json::json;
use squint_testkit::mcp_client::Client;

fn repo_root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../..")
        .canonicalize()
        .unwrap()
}

fn out(tag: &str) -> PathBuf {
    let dir = std::env::temp_dir().join(format!(
        "squint-fixtures-served-{tag}-{}",
        std::process::id()
    ));
    let _ = std::fs::remove_dir_all(&dir);
    dir
}

fn client(out: &Path, script: &str) -> Client {
    let mut c = Command::new(env!("CARGO_BIN_EXE_squint"));
    c.current_dir(repo_root())
        .args([
            "serve",
            "--config",
            "fixtures/config/minimal.toml",
            "--provider-script",
        ])
        .arg(repo_root().join("fixtures/scripts").join(script))
        .arg("--out")
        .arg(out);
    let mut client = Client::start(&mut c).unwrap();
    client.roots = vec![format!(
        "file://{}",
        repo_root().join("fixtures/images").display()
    )];
    client
}

fn pair() -> serde_json::Value {
    let image = |n: &str| json!({ "path": repo_root().join("fixtures/images").join(n) });
    json!({ "candidate": image("candidate-64x48.png"), "source": image("source-64x48.png") })
}

/// A document valid against one of the contract's schemas, by id.
fn valid(id: &str, doc: &serde_json::Value) {
    struct Embedded;
    impl jsonschema::Retrieve for Embedded {
        fn retrieve(
            &self,
            uri: &jsonschema::Uri<String>,
        ) -> Result<serde_json::Value, Box<dyn std::error::Error + Send + Sync>> {
            let (_, text) = table_manners::SCHEMAS
                .iter()
                .find(|(id, _)| *id == uri.as_str())
                .ok_or("unknown schema")?;
            Ok(serde_json::from_str(text)?)
        }
    }
    let (_, text) = table_manners::SCHEMAS
        .iter()
        .find(|(schema, _)| *schema == id)
        .unwrap();
    let schema: serde_json::Value = serde_json::from_str(text).unwrap();
    let validator = jsonschema::options()
        .with_retriever(Embedded)
        .build(&schema)
        .unwrap();
    let errors: Vec<String> = validator.iter_errors(doc).map(|e| e.to_string()).collect();
    assert!(errors.is_empty(), "{id}: {errors:?}\n{doc}");
}

/// The session id every fixture uses, as rascal's do.
const SESSION: &str = "00000000-0000-4000-8000-000000000001";
const CLIENT: &str = "table-manners/client_run_id";

/// `doc` with the run's machine values fixed: the output directory, run ids (renamed by
/// `names`), the session id, times, durations, versions and input identities.
fn fix(
    doc: &serde_json::Value,
    out: &Path,
    session: &str,
    names: &[(String, &str)],
) -> serde_json::Value {
    let mut text = doc.to_string();
    text = text.replace(&out.canonicalize().unwrap().display().to_string(), "/runs");
    text = text.replace(&out.display().to_string(), "/runs");
    text = text.replace(session, SESSION);
    for (id, name) in names {
        text = text.replace(id.as_str(), name);
    }
    let mut doc: serde_json::Value = serde_json::from_str(&text).unwrap();
    fn walk(v: &mut serde_json::Value) {
        match v {
            serde_json::Value::Object(map) => {
                for (key, value) in map.iter_mut() {
                    match key.as_str() {
                        "started" | "finished" if value.is_string() => {
                            *value = "2026-01-01T00:00:00.000Z".into();
                        }
                        "duration_ms" => *value = 0.into(),
                        "input_identity" => {
                            *value = format!("sha256:{}", "0".repeat(64)).into();
                        }
                        "tool" if value.get("version").is_some() => {
                            value["version"] = "0.0.0".into();
                        }
                        _ => walk(value),
                    }
                }
            }
            serde_json::Value::Array(items) => items.iter_mut().for_each(walk),
            _ => {}
        }
    }
    walk(&mut doc);
    doc
}

fn check(name: &str, now: &serde_json::Value) {
    let path = repo_root().join("fixtures/contract/squint").join(name);
    let text = serde_json::to_string_pretty(now).unwrap() + "\n";
    if std::env::var_os("UPDATE_CONTRACT_FIXTURES").is_some() {
        std::fs::write(&path, &text).unwrap();
    }
    assert_eq!(
        std::fs::read_to_string(&path).unwrap_or_default(),
        text,
        "{} drifted from what squint serves; review, then UPDATE_CONTRACT_FIXTURES=1 and copy to table-manners",
        path.display()
    );
}

fn refusal(
    r: Result<squint_testkit::mcp_client::CallResult, squint_testkit::mcp_client::Failure>,
) -> serde_json::Value {
    match r {
        Err(squint_testkit::mcp_client::Failure::Rpc {
            data: Some(data), ..
        }) => data,
        other => panic!("expected a refusal, got {other:?}"),
    }
}

#[test]
fn the_served_fixtures_are_what_squint_serves() {
    let out = out("all");
    let mut c = client(&out, "slow-retry.json");
    let session: serde_json::Value =
        serde_json::from_str(&c.read_resource("squint://session").unwrap()).unwrap();
    let session_id = session["id"].as_str().unwrap().to_string();

    // A check that waits on a retry holds an id while queued work is refused with no run yet.
    let running = c
        .start_call_with_meta(
            "source_fidelity",
            pair(),
            json!({ "progressToken": "a", CLIENT: "host-attempt-1" }),
        )
        .unwrap();
    loop {
        let n = c.next_notification().unwrap();
        if n["params"]["message"]
            .as_str()
            .is_some_and(|m| m.starts_with("waiting"))
        {
            break;
        }
    }
    let queued = c
        .start_call_with_meta(
            "source_fidelity",
            pair(),
            json!({ "progressToken": "q", CLIENT: "host-attempt-2" }),
        )
        .unwrap();
    // Its first heartbeat: accepted, so its id is claimed, and waiting for the permit, so the
    // cancel lands there. Two requests in flight together have no guaranteed order.
    while c.next_notification().unwrap()["params"]["progressToken"] != "q" {}
    c.cancel(queued).unwrap();
    std::thread::sleep(std::time::Duration::from_millis(300));
    let no_run = refusal(c.call_with_meta(
        "source_fidelity",
        pair(),
        json!({ CLIENT: "host-attempt-2" }),
    ));
    // The waiting check is cancelled during its retry wait: its failed attempt is unresolved.
    c.cancel(running).unwrap();
    let mut cancelled = None;
    for _ in 0..100 {
        let runs: serde_json::Value =
            serde_json::from_str(&c.read_resource("squint://runs").unwrap()).unwrap();
        if let Some(r) = runs["runs"]
            .as_array()
            .unwrap()
            .iter()
            .find(|r| r["status"] == "cancelled")
        {
            cancelled = Some(r["id"].as_str().unwrap().to_string());
            break;
        }
        std::thread::sleep(std::time::Duration::from_millis(100));
    }
    let cancelled = cancelled.expect("the check was cancelled");
    let earlier = refusal(c.call_with_meta(
        "source_fidelity",
        pair(),
        json!({ CLIENT: "host-attempt-1" }),
    ));
    let served: serde_json::Value = serde_json::from_str(
        &c.read_resource(&format!("squint://run/{cancelled}/run.json"))
            .unwrap(),
    )
    .unwrap();
    let runs: serde_json::Value =
        serde_json::from_str(&c.read_resource("squint://runs").unwrap()).unwrap();
    let session: serde_json::Value =
        serde_json::from_str(&c.read_resource("squint://session").unwrap()).unwrap();

    let names = [(cancelled.clone(), "served-cancelled")];
    for (name, doc, schema) in [
        (
            "run-served-cancelled-unresolved.json",
            &served,
            "urn:table-manners:core:result",
        ),
        ("runs.json", &runs, "urn:table-manners:core:runs"),
        ("session.json", &session, "urn:table-manners:core:session"),
        (
            "refusal-earlier-run.json",
            &earlier,
            "urn:table-manners:core:refusal",
        ),
        (
            "refusal-no-run.json",
            &no_run,
            "urn:table-manners:core:refusal",
        ),
    ] {
        let fixed = fix(doc, &out, &session_id, &names);
        valid(schema, &fixed);
        check(name, &fixed);
    }
}
